public static void main(String[] args) {
    test("a new order has no tags", () ->
        eq(Order.create(1).tags(), List.of()));
    test("tagging one order leaves another untouched", () -> {
        var a = Order.create(1);
        var b = Order.create(2);
        a.addTag("rush");
        eq(a.tags(), List.of("rush"));
        eq(b.tags(), List.of());
    });
    test("two fresh orders never share a list", () -> {
        var a = Order.create(1);
        var b = Order.create(2);
        a.addTag("x");
        b.addTag("y");
        eq(a.tags(), List.of("x"));
        eq(b.tags(), List.of("y"));
    });
    test("editing the returned tags changes nothing", () -> {
        var a = Order.create(1);
        a.addTag("rush");
        var t = a.tags();
        try {
            t.add("x");
        } catch (UnsupportedOperationException ignored) {
            // an unmodifiable snapshot is fine too
        }
        eq(a.tags(), List.of("rush"));
    });
    test("withTags copies its input", () -> {
        var src = new ArrayList<>(List.of("gift"));
        var c = Order.withTags(3, src);
        src.add("x");
        eq(c.tags(), List.of("gift"));
    });
    test("tagging a copied order leaves the caller's list alone", () -> {
        var src = new ArrayList<>(List.of("gift"));
        var c = Order.withTags(3, src);
        c.addTag("rush");
        eq(c.tags(), List.of("gift", "rush"));
        eq(src, List.of("gift"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

