// ─────────────────────────────────────────────────────────────────────────
//  02 · same key, different body                                     ★★★
//  concepts: idempotency keys · payload fingerprint · half-open TTL window
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {
    /** Replays a retried request instead of charging twice. */
    static final class IdempotencyStore {
        private record Entry(String hash, long createdAt, int chargeNo) {}

        private final int ttlSeconds;
        private final Map<String, Entry> byKey = new HashMap<>();
        private int charges;

        IdempotencyStore(int ttlSeconds) {
            this.ttlSeconds = ttlSeconds;
        }

        /** "CREATED:n", "REPLAY:n" or "CONFLICT"; an entry is live while now < createdAt + ttl. */
        String handle(String key, String payloadHash, long nowSeconds) {
            Entry e = byKey.get(key);
            if (e != null && nowSeconds < e.createdAt() + ttlSeconds) {
                return e.hash().equals(payloadHash) ? "REPLAY:" + e.chargeNo() : "CONFLICT";
            }
            charges++;
            byKey.put(key, new Entry(payloadHash, nowSeconds, charges));
            return "CREATED:" + charges;
        }

        /** How many charges were created so far. */
        int charges() {
            return charges;
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
