// ─────────────────────────────────────────────────────────────────────────
//  06 · page 10 of 10 was empty                                      ★★☆
//  concepts: integer ceiling · clamped slice bounds · 1-based pages
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {
    /** ceil(total / size); size must be at least 1. */
    static int pageCount(int total, int size) {
        if (size < 1) {
            throw new IllegalArgumentException("size must be at least 1");
        }
        return (int) ((total + (long) size - 1) / size);
    }

    /** [startInclusive, endExclusive] of a 1-based page, or empty past the end. */
    static List<Integer> pageSlice(int total, int size, int page) {
        if (size < 1 || page < 1) {
            throw new IllegalArgumentException("page and size must be at least 1");
        }
        long start = (long) (page - 1) * size;
        if (start >= total) {
            return List.of();
        }
        return List.of((int) start, (int) Math.min(start + size, total));
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("the page count of nothing is 0", () ->
            eq(pageCount(0, 10), 0));
        test("partial and exact pages", () -> {
            eq(pageCount(1, 10), 1);
            eq(pageCount(10, 10), 1);
            eq(pageCount(11, 10), 2);
